{
  "name": "泰克 TDS2024 数字实时示波器",
  "name_en": "Tektronix TDS2024 Digital Real-Time Oscilloscope",
  "manufacturer": "Tektronix",
  "description": "一款 200 MHz、4 通道数字实时示波器，用于采集、显示和测量电信号波形。该设备可进行触发控制、通道选择、波形数据读取以及频率、最小值、最大值和平均值等即时测量，适用于电子实验与信号调试。",
  "description_en": "A 200 MHz, 4-channel digital real-time oscilloscope used to acquire, display, and measure electrical waveforms. It supports trigger control, channel selection, waveform data readout, and immediate measurements such as frequency, minimum, maximum, and mean, making it suitable for electronics experiments and signal debugging.",
  "actions": [
    {
      "action_name": "auto-initialize",
      "description": "初始化示波器通信与设备状态。",
      "description_en": "Initialize oscilloscope communication and device state."
    },
    {
      "action_name": "auto-autoconf",
      "description": "自动配置示波器以适应当前输入信号。",
      "description_en": "Automatically configure the oscilloscope for the current input signal."
    },
    {
      "action_name": "auto-idn",
      "description": "读取设备身份信息。",
      "description_en": "Read the device identification information."
    },
    {
      "action_name": "auto-trigger",
      "description": "获取或设置触发状态/模式。",
      "description_en": "Get or set the trigger state/mode."
    },
    {
      "action_name": "auto-triggerlevel",
      "description": "将触发电平设置为信号最小值与最大值之间的 50%。",
      "description_en": "Set the trigger level to 50% between the signal minimum and maximum."
    },
    {
      "action_name": "auto-forcetrigger",
      "description": "强制产生一次触发事件。",
      "description_en": "Force a trigger event."
    },
    {
      "action_name": "auto-datasource",
      "description": "选择波形数据采集的输入通道。",
      "description_en": "Select the input channel used as the waveform data source."
    },
    {
      "action_name": "auto-acqparams",
      "description": "读取波形采集参数，如 X/Y 增量、原点和偏移量。",
      "description_en": "Read waveform acquisition parameters such as X/Y increment, origin, and offset."
    },
    {
      "action_name": "auto-dataencoding",
      "description": "设置波形数据传输编码格式。",
      "description_en": "Set the waveform data transfer encoding format."
    },
    {
      "action_name": "auto-curv",
      "description": "读取当前波形数据，返回时间轴与采样值。",
      "description_en": "Read the current waveform data and return the time axis and sampled values."
    },
    {
      "action_name": "auto-measure_frequency",
      "description": "测量指定通道信号的频率。",
      "description_en": "Measure the frequency of the signal on the specified channel."
    },
    {
      "action_name": "auto-measure_min",
      "description": "测量指定通道信号的最小值。",
      "description_en": "Measure the minimum value of the signal on the specified channel."
    },
    {
      "action_name": "auto-measure_max",
      "description": "测量指定通道信号的最大值。",
      "description_en": "Measure the maximum value of the signal on the specified channel."
    },
    {
      "action_name": "auto-measure_mean",
      "description": "测量指定通道信号的平均值。",
      "description_en": "Measure the mean value of the signal on the specified channel."
    }
  ],
  "tag_hints": [
    "digital oscilloscope",
    "waveform acquisition",
    "trigger control",
    "electrical signal measurement",
    "4-channel oscilloscope",
    "200 MHz bandwidth",
    "waveform readout",
    "Tektronix TDS2000 series"
  ]
}

